/* ===== Kraftlog — Signal-Primitiven für den Pausen-Timer =====
 * Die Countdown-Logik lebt in app.js (rein timestampbasiert).
 * Hier: Web-Audio-Piepton (Vordergrund), Audio-Element-Piepton (läuft auch im
 * Hintergrund, solange die Audio-Session gehalten wird), Vibration sowie der
 * Hintergrund-Trick: Während der Pause läuft eine (stumme) Audio-Schleife —
 * sie hält die App auch bei gesperrtem Handy/anderer App am Leben, damit
 * Ton und Benachrichtigung am Pausenende ausgelöst werden können.
 * iOS-Regel: Audio muss in einer Nutzer-Geste entsperrt werden (erster Satz-Haken).
 * Pausenende-Signal ist der "Let's go"-Clip (DaBaby, 3 s, als Data-URI eingebettet —
 * die App bleibt damit offline-tauglich und die Single-File-Variante laedt nichts nach);
 * die Glocke bleibt als Rueckfall, falls der Clip nicht abgespielt werden darf.
 */
window.KraftlogTimer = (function () {
  'use strict';

  var BEEP_WAV = 'data:audio/wav;base64,';
  var STILLE_WAV = 'data:audio/wav;base64,';
  var LETSGO_MP3 = 'data:audio/mpeg;base64,';

  var ctx = null;
  var beepEl = null;
  var stilleEl = null;
  var hypeEl = null;

  function ensureEls() {
    if (beepEl) return;
    try {
      beepEl = new Audio(BEEP_WAV);
      beepEl.setAttribute('playsinline', '');
      stilleEl = new Audio(STILLE_WAV);
      stilleEl.setAttribute('playsinline', '');
      stilleEl.loop = true;
      hypeEl = new Audio(LETSGO_MP3);
      hypeEl.setAttribute('playsinline', '');
      hypeEl.preload = 'auto';
    } catch (e) { beepEl = null; stilleEl = null; hypeEl = null; }
  }

  /* iOS-Audio-Session (Safari 17+): 'ambient' mischt sich mit Musik statt sie zu stoppen;
     'transient' duckt Musik kurz fuer die Glocke; 'playback' haelt die App im Hintergrund wach
     (nur im Opt-in-Modus "Signal bei gesperrtem Handy" - unterbricht dann Musik). */
  function session(typ) {
    try { if (navigator.audioSession) navigator.audioSession.type = typ; } catch (e) { }
  }

  function ensureCtx() {
    if (!ctx) {
      var AC = window.AudioContext || window.webkitAudioContext;
      if (AC) { try { ctx = new AC(); } catch (e) { ctx = null; } }
    }
    return ctx;
  }

  /* In einer Nutzer-Geste aufrufen (erster Satz-Haken): entsperrt WebAudio UND die Audio-Elemente. */
  function unlock() {
    session('ambient');
    var c = ensureCtx();
    if (c) {
      try {
        if (c.state === 'suspended') c.resume();
        var buf = c.createBuffer(1, 1, 22050);
        var src = c.createBufferSource();
        src.buffer = buf;
        src.connect(c.destination);
        src.start(0);
      } catch (e) { }
    }
    ensureEls();
    [beepEl, hypeEl].forEach(entsperreEl);
  }

  /* Stumm anspielen und sofort zurueckspulen: danach darf das Element auch ohne
     Geste tonen (iOS merkt sich die Freigabe pro Element, nicht pro Datei). */
  function entsperreEl(el) {
    if (!el) return;
    try {
      el.muted = true;
      var p = el.play();
      if (p && p.then) {
        p.then(function () { el.pause(); el.currentTime = 0; el.muted = false; })
          .catch(function () { el.muted = false; });
      }
    } catch (e) { try { el.muted = false; } catch (e2) { } }
  }

  /* Glockenklang (Vordergrund, WebAudio): zwei sanfte Anschläge mit Obertönen. */
  function beep() {
    session('transient');
    setTimeout(function () { session('ambient'); }, 2500);
    var c = ensureCtx();
    if (!c || c.state !== 'running') return false;
    try {
      var start = c.currentTime + 0.02;
      for (var k = 0; k < 2; k++) {
        var t = start + k * 0.7;
        var freqs = [660, 1320, 1980];
        var gains = [0.30, 0.12, 0.05];
        for (var j = 0; j < freqs.length; j++) {
          var osc = c.createOscillator();
          var g = c.createGain();
          osc.type = 'sine';
          osc.frequency.value = freqs[j];
          g.gain.setValueAtTime(gains[j], t);
          g.gain.exponentialRampToValueAtTime(0.0001, t + 0.6);
          osc.connect(g).connect(c.destination);
          osc.start(t);
          osc.stop(t + 0.65);
        }
      }
      return true;
    } catch (e) { return false; }
  }

  /* Piepton über das Audio-Element — funktioniert auch im Hintergrund/gesperrt,
     solange die stille Schleife die Audio-Session hält. */
  function beepLaut() {
    session('transient');
    setTimeout(function () { session('ambient'); }, 2500);
    ensureEls();
    if (!beepEl) return false;
    try {
      beepEl.currentTime = 0;
      var p = beepEl.play();
      if (p && p.catch) p.catch(function () { });
      return true;
    } catch (e) { return false; }
  }

  /* Pausenende: "Let's go". Laeuft ueber ein Audio-Element, funktioniert also auch
     im Hintergrund, solange die Audio-Session gehalten wird. Darf der Clip nicht
     spielen (Autoplay-Sperre, Element fehlt), uebernimmt `zurueckfall` — sonst
     ginge das Pausenende komplett lautlos vorbei. */
  function hype(zurueckfall) {
    session('transient');
    setTimeout(function () { session('ambient'); }, 4000);
    ensureEls();
    if (!hypeEl) { if (zurueckfall) zurueckfall(); return false; }
    try {
      hypeEl.currentTime = 0;
      var p = hypeEl.play();
      if (p && p.catch) p.catch(function () { if (zurueckfall) zurueckfall(); });
      return true;
    } catch (e) { if (zurueckfall) zurueckfall(); return false; }
  }

  /* Pause beginnt: stille Schleife starten (haelt die App im Hintergrund wach). */
  function restStart() {
    session('playback');
    ensureEls();
    if (!stilleEl) return;
    try {
      var p = stilleEl.play();
      if (p && p.catch) p.catch(function () { });
      if ('mediaSession' in navigator && window.MediaMetadata) {
        try {
          navigator.mediaSession.metadata = new MediaMetadata({ title: 'Pausen-Timer laeuft', artist: 'Kraftlog' });
        } catch (e) { }
      }
    } catch (e) { }
  }

  /* Pause beendet: Schleife stoppen. */
  function restStop() {
    session('ambient');
    if (!stilleEl) return;
    try { stilleEl.pause(); stilleEl.currentTime = 0; } catch (e) { }
  }

  function vibrate() {
    try { if (navigator.vibrate) navigator.vibrate([200, 100, 200]); } catch (e) { }
  }

  return { unlock: unlock, beep: beep, beepLaut: beepLaut, hype: hype, restStart: restStart, restStop: restStop, vibrate: vibrate };
})();
